package main

import (
	"fmt"
	"os/exec"
	"strings"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Basic input validation to prevent shell injection
	if strings.ContainsAny(loadBalancerName, "`$\n\r\t|>&; ") || strings.ContainsAny(outputFile, "`$\n\r\t|>&; ") {
		return "", fmt.Errorf("invalid characters in input parameters")
	}

	// Construct the command pipeline using separate commands for safety
	// Step 1: aliyun slb DescribeLoadBalancers
	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// Step 2: jq filter
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Create pipes between commands
	aliyunOut, err := aliyunCmd.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create pipe for aliyun: %w", err)
	}

	jqOut, err := jqCmd.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create pipe for jq: %w", err)
	}

	// Start aliyun command
	if err := aliyunCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}

	// Feed aliyun output to jq stdin
	jqCmd.Stdin = aliyunOut

	// Start jq command
	if err := jqCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Write jq output to file using tee
	teeCmd := exec.Command("tee", outputFile)
	teeCmd.Stdin = jqOut

	// Capture combined output
	outputBytes, err := teeCmd.CombinedOutput()
	if err != nil {
		return string(outputBytes), fmt.Errorf("tee command failed: %w", err)
	}

	// Wait for aliyun and jq to complete
	if err := aliyunCmd.Wait(); err != nil {
		return string(outputBytes), fmt.Errorf("aliyun command failed: %w", err)
	}
	if err := jqCmd.Wait(); err != nil {
		return string(outputBytes), fmt.Errorf("jq command failed: %w", err)
	}

	return string(outputBytes), nil
}

