package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Validate loadBalancerName: only allow alphanumeric characters, hyphens, and underscores
	if !isValidName(loadBalancerName) {
		return "", fmt.Errorf("invalid loadBalancerName: must contain only alphanumeric characters, hyphens, and underscores")
	}

	// Validate and sanitize outputFile path
	cleanPath, err := sanitizePath(outputFile)
	if err != nil {
		return "", fmt.Errorf("invalid outputFile path: %w", err)
	}

	// Step 1: Execute aliyun command with safe argument passing
	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers",
		"--LoadBalancerName", loadBalancerName)

	// Step 2: Execute jq command to filter output
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Set up pipeline: aliyunCmd stdout -> jqCmd stdin
	jqCmd.Stdin, err = aliyunCmd.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create pipe: %w", err)
	}

	// Set up output file
	outFile, err := os.Create(cleanPath)
	if err != nil {
		return "", fmt.Errorf("failed to create output file: %w", err)
	}
	defer outFile.Close()

	jqCmd.Stdout = outFile

	// Capture stderr from both commands
	var stderrBuf strings.Builder
	aliyunCmd.Stderr = &stderrBuf
	jqCmd.Stderr = &stderrBuf

	// Start jq command
	if err := jqCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start jq: %w", err)
	}

	// Run aliyun command (this will write to jq's stdin)
	if err := aliyunCmd.Run(); err != nil {
		// Wait for jq to finish
		jqCmd.Wait()
		return stderrBuf.String(), fmt.Errorf("aliyun command failed: %w, stderr: %s", err, stderrBuf.String())
	}

	// Wait for jq to finish processing
	if err := jqCmd.Wait(); err != nil {
		return stderrBuf.String(), fmt.Errorf("jq command failed: %w, stderr: %s", err, stderrBuf.String())
	}

	// Read the output file content for return value
	outputBytes, err := os.ReadFile(cleanPath)
	if err != nil {
		return "", fmt.Errorf("failed to read output file: %w", err)
	}

	return string(outputBytes), nil
}

// isValidName checks if the name contains only safe characters
func isValidName(name string) bool {
	if len(name) == 0 {
		return false
	}
	for _, r := range name {
		if !((r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') ||
			(r >= '0' && r <= '9') || r == '-' || r == '_') {
			return false
		}
	}
	return true
}

// sanitizePath validates and cleans the file path to prevent directory traversal
func sanitizePath(path string) (string, error) {
	// Clean the path to remove any ".." or other traversal attempts
	clean := filepath.Clean(path)

	// Ensure the path is not absolute (for security, we only allow relative paths)
	if filepath.IsAbs(clean) {
		return "", fmt.Errorf("absolute paths are not allowed")
	}

	// Check for directory traversal attempts
	if strings.Contains(clean, "..") {
		return "", fmt.Errorf("directory traversal is not allowed")
	}

	// Verify the path doesn't contain shell special characters
	disallowed := "`$|;&()<>{}[]!?"
	if strings.ContainsAny(clean, disallowed) {
		return "", fmt.Errorf("path contains disallowed characters")
	}

	return clean, nil
}

