package main

import (
	"bytes"
	"fmt"
	"os/exec"
)

// QuerySLBAndExport runs the aliyun CLI command to query SLB information
// and exports the result to a JSON file using jq for formatting.
// Parameters:
//   - loadBalancerName: the name of the load balancer to query
//   - outputFile: the path to the output JSON file
// Returns:
//   - string: the combined output (stdout + stderr) from the command
//   - error: any error encountered during execution
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Build the command: aliyun slb DescribeLoadBalancers --LoadBalancerName NAME | jq '.LoadBalancers.LoadBalancer[]' > outputFile
	cmd := exec.Command("sh", "-c",
		fmt.Sprintf("aliyun slb DescribeLoadBalancers --LoadBalancerName %s | jq '.LoadBalancers.LoadBalancer[]' > %s",
			loadBalancerName, outputFile))

	// Capture stdout and stderr
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	// Run the command
	err := cmd.Run()
	if err != nil {
		return stderr.String(), fmt.Errorf("command execution failed: %w, stderr: %s", err, stderr.String())
	}

	// Return combined output (stdout has the jq output which went to file, but we still capture it)
	return stdout.String(), nil
}

func main() {
	// Example usage
	result, err := QuerySLBAndExport("my-load-balancer", "output.json")
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}
	fmt.Printf("Command executed successfully. Output: %s\n", result)
}

