package main

import (
	"bytes"
	"fmt"
	"os/exec"
	"strings"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Basic input validation to prevent obvious shell injection
	if strings.ContainsAny(loadBalancerName, "`$\n\r\t|>") || strings.ContainsAny(outputFile, "`$\n\r\t|>") {
		return "", fmt.Errorf("invalid characters in input parameters")
	}

	// Build the command pipeline using separate arguments for security
	// aliyun slb DescribeLoadBalancers --LoadBalancerName NAME | jq '.LoadBalancers.LoadBalancer[]' > output.json
	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Create pipe from aliyun stdout to jq stdin
	jqStdin, err := aliyunCmd.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create pipe from aliyun: %w", err)
	}
	jqCmd.Stdin = jqStdin

	// Capture jq stdout to both buffer and file
	var jqStdout bytes.Buffer
	jqCmd.Stdout = &jqStdout

	// Start aliyun command
	if err := aliyunCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}

	// Start jq command
	if err := jqCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Wait for aliyun to finish
	if err := aliyunCmd.Wait(); err != nil {
		return "", fmt.Errorf("aliyun command failed: %w", err)
	}

	// Close jq stdin to signal end of input
	if err := jqStdin.Close(); err != nil {
		return "", fmt.Errorf("failed to close jq stdin: %w", err)
	}

	// Wait for jq to finish
	if err := jqCmd.Wait(); err != nil {
		return "", fmt.Errorf("jq command failed: %w", err)
	}

	// Write output to file
	if err := writeFile(outputFile, jqStdout.Bytes()); err != nil {
		return "", fmt.Errorf("failed to write output to file: %w", err)
	}

	return jqStdout.String(), nil
}

// writeFile writes data to a file
func writeFile(filename string, data []byte) error {
	cmd := exec.Command("tee", filename)
	cmd.Stdin = bytes.NewReader(data)
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return fmt.Errorf("failed to write file: %w, stderr: %s", err, stderr.String())
	}
	return nil
}

