package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Validate loadBalancerName: only allow alphanumeric characters, hyphens, and underscores
	if !isValidName(loadBalancerName) {
		return "", fmt.Errorf("invalid loadBalancerName: must contain only alphanumeric characters, hyphens, and underscores")
	}

	// Validate and sanitize outputFile path
	cleanOutputFile, err := sanitizeFilePath(outputFile)
	if err != nil {
		return "", fmt.Errorf("invalid outputFile path: %w", err)
	}

	// Step 1: Execute aliyun command with properly escaped arguments
	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
	aliyunOut, err := aliyunCmd.Output()
	if err != nil {
		return "", fmt.Errorf("aliyun command failed: %w", err)
	}

	// Step 2: Execute jq command with the aliyun output piped via stdin
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")
	jqCmd.Stdin = strings.NewReader(string(aliyunOut))
	jqOut, err := jqCmd.Output()
	if err != nil {
		return "", fmt.Errorf("jq command failed: %w", err)
	}

	// Step 3: Write jq output to the specified file
	if err := os.WriteFile(cleanOutputFile, jqOut, 0644); err != nil {
		return "", fmt.Errorf("failed to write output file: %w", err)
	}

	return string(jqOut), nil
}

// isValidName checks if the string contains only safe characters
func isValidName(name string) bool {
	if len(name) == 0 {
		return false
	}
	for _, r := range name {
		if !((r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '-' || r == '_') {
			return false
		}
	}
	return true
}

// sanitizeFilePath cleans and validates a file path
func sanitizeFilePath(path string) (string, error) {
	// Clean the path to remove any traversal attempts
	cleanPath := filepath.Clean(path)

	// Ensure the path doesn't contain directory traversal
	if strings.Contains(cleanPath, "..") {
		return "", fmt.Errorf("path traversal detected")
	}

	// Get absolute path to prevent relative path issues
	absPath, err := filepath.Abs(cleanPath)
	if err != nil {
		return "", fmt.Errorf("cannot get absolute path: %w", err)
	}

	// Verify the parent directory exists
	parentDir := filepath.Dir(absPath)
	if _, err := os.Stat(parentDir); os.IsNotExist(err) {
		return "", fmt.Errorf("parent directory does not exist: %s", parentDir)
	}

	return absPath, nil
}

