	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers",
		fmt.Sprintf("--LoadBalancerName=%s", loadBalancerName))

	// Step 2: Create jq command to process output
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Step 3: Create output file
	outputCmd := exec.Command("tee", outputFile)

	// Build pipeline: aliyun | jq | tee outputFile
	var err error
	jqCmd.Stdin, err = aliyunCmd.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create pipe: %w", err)
