		return "", fmt.Errorf("failed to start jq command: %w", err)
	}
	if err := aliyunCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}

	// Wait for commands to complete (from first to last)
	if err := aliyunCmd.Wait(); err != nil {
		return "", fmt.Errorf("aliyun command failed: %w", err)
	}
	if err := jqCmd.Wait(); err != nil {
		return "", fmt.Errorf("jq command failed: %w", err)
	}
	if err := outputCmd.Wait(); err != nil {
		return "", fmt.Errorf("tee command failed: %w", err)
	}

	// Capture final output after all commands have completed
	outputBytes, err := outputCmd.Output()
	if err != nil {
		return "", fmt.Errorf("command pipeline failed: %w", err)
	}

	return string(outputBytes), nil
}

