	"os/exec"
	"path/filepath"
	"strings"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Validate loadBalancerName - only allow alphanumeric characters, hyphens, and underscores
	if !isValidName(loadBalancerName) {
		return "", fmt.Errorf("invalid loadBalancerName: must contain only alphanumeric characters, hyphens, and underscores")
	}

	// Validate and sanitize outputFile path
	outputFile = filepath.Clean(outputFile)
	if outputFile == "" || outputFile == "." || outputFile == ".." {
		return "", fmt.Errorf("invalid outputFile path")
	}

	// Ensure the output directory exists
	outputDir := filepath.Dir(outputFile)
	if outputDir != "." {
		if err := os.MkdirAll(outputDir, 0755); err != nil {
			return "", fmt.Errorf("failed to create output directory: %w", err)
		}
	}

	// Create the output file
	file, err := os.Create(outputFile)
	if err != nil {
		return "", fmt.Errorf("failed to create output file: %w", err)
	}
	defer file.Close()

	// Execute aliyun command with properly separated arguments
	aliyunArgs := []string{
		"slb",
		"DescribeLoadBalancers",
		fmt.Sprintf("--LoadBalancerName=%s", loadBalancerName),
	}
	aliyunCmd := exec.Command("aliyun", aliyunArgs...)

	// Execute jq command
	jqArgs := []string{
		".LoadBalancers.LoadBalancer[]",
	}
	jqCmd := exec.Command("jq", jqArgs...)

	// Create pipeline: aliyun -> jq -> file
	jqCmd.Stdin, err = aliyunCmd.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create pipe: %w", err)
	}
	jqCmd.Stdout = file

	// Capture stderr from both commands
	var stderrBuilder strings.Builder
	aliyunCmd.Stderr = &stderrBuilder
	jqCmd.Stderr = &stderrBuilder

	// Start jq first (it will wait for input)
	if err := jqCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start jq: %w", err)
	}

	// Run aliyun command
	if err := aliyunCmd.Run(); err != nil {
		// Wait for jq to finish
		jqCmd.Wait()
		return stderrBuilder.String(), fmt.Errorf("aliyun command failed: %w, stderr: %s", err, stderrBuilder.String())
	}

	// Wait for jq to finish processing
	if err := jqCmd.Wait(); err != nil {
		return stderrBuilder.String(), fmt.Errorf("jq command failed: %w, stderr: %s", err, stderrBuilder.String())
	}

	return fmt.Sprintf("Output written to %s successfully", outputFile), nil
}

// isValidName checks if the name contains only safe characters
func isValidName(name string) bool {
	if len(name) == 0 {
		return false
	}
	for _, r := range name {
		if !((r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '-' || r == '_') {
			return false
		}
	}
	return true
}

