        "--LoadBalancerName", loadBalancerName)

    // Create jq command for processing
    jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

    // Create output file
    outputCmd := exec.Command("tee", outputFile)

    // Set up pipeline: aliyun -> jq -> file
    cmdOut, err := cmd.StdoutPipe()
    if err != nil {
        return "", fmt.Errorf("failed to create stdout pipe for aliyun: %w", err)
    }
    jqCmd.Stdin = cmdOut

    jqOut, err := jqCmd.StdoutPipe()
    if err != nil {
        return "", fmt.Errorf("failed to create stdout pipe for jq: %w", err)
    }
    outputCmd.Stdin = jqOut

    // Capture output from tee command
    var outputBuf bytes.Buffer
    outputCmd.Stdout = &outputBuf

    // Start commands in order
    if err := cmd.Start(); err != nil {
        return "", fmt.Errorf("failed to start aliyun command: %w", err)
    }
    if err := jqCmd.Start(); err != nil {
        return "", fmt.Errorf("failed to start jq command: %w", err)
    }
    if err := outputCmd.Start(); err != nil {
        return "", fmt.Errorf("failed to start tee command: %w", err)
    }

    // Wait for all commands to complete
    if err := cmd.Wait(); err != nil {
        return "", fmt.Errorf("aliyun command failed: %w", err)
    }
    if err := jqCmd.Wait(); err != nil {
        return "", fmt.Errorf("jq command failed: %w", err)
    }
    if err := outputCmd.Wait(); err != nil {
        return "", fmt.Errorf("tee command failed: %w", err)
    }

    // Read output from buffer
    outputBytes, err := io.ReadAll(&outputBuf)
    if err != nil {
        return "", fmt.Errorf("failed to read command output: %w", err)
    }

    return string(outputBytes), nil
}

// validateInput checks for potentially dangerous characters in input parameters
func validateInput(loadBalancerName string, outputFile string) error {
    // Define characters that could be used for command injection
    dangerousChars := "`$;&|(){}[]<>#!?*~"

    for _, char := range dangerousChars {
        if strings.ContainsRune(loadBalancerName, char) {
