// QuerySLBAndExport queries SLB information using aliyun CLI and exports it to a file.
// It constructs the command: aliyun slb DescribeLoadBalancers --LoadBalancerName NAME | jq '.LoadBalancers.LoadBalancer[]' > output.json
// Returns the command output (stdout) and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Build the full shell command
	shellCmd := fmt.Sprintf("aliyun slb DescribeLoadBalancers --LoadBalancerName %s | jq '.LoadBalancers.LoadBalancer[]' > %s", 
