		return strings.TrimSpace(stdout.String()) + "\n" + strings.TrimSpace(stderr.String()), nil
	}

	return strings.TrimSpace(stdout.String()), nil
}

// shellEscape escapes special characters in a string for use in shell commands
func shellEscape(s string) string {
	// Replace single quotes with end-quote, escaped quote, start-quote
	s = strings.ReplaceAll(s, "'", "'\\''")
	// Wrap in single quotes to prevent word splitting and glob expansion
	return "'" + s + "'"
}

