// QuerySLBAndExport executes the aliyun CLI command to query SLB information
// and exports the result to a specified file using jq for formatting.
// Parameters:
//   - loadBalancerName: the name of the load balancer to query
//   - outputFile: the file path where the output will be written
// Returns:
//   - string: the command output (stdout) as a string
//   - error: any error encountered during execution
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Validate input parameters
	if strings.TrimSpace(loadBalancerName) == "" {
		return "", fmt.Errorf("loadBalancerName cannot be empty")
	}
	if strings.TrimSpace(outputFile) == "" {
		return "", fmt.Errorf("outputFile cannot be empty")
	}

	// Build the command pipeline:
	// aliyun slb DescribeLoadBalancers --LoadBalancerName NAME | jq '.LoadBalancers.LoadBalancer[]' > output.json
	// We'll use shell piping via bash -c to handle the pipeline and redirection

	// Construct the shell command
	shellCmd := fmt.Sprintf(
		"aliyun slb DescribeLoadBalancers --LoadBalancerName %s | jq '.LoadBalancers.LoadBalancer[]' > %s",
		shellEscape(loadBalancerName),
		shellEscape(outputFile),
	)

	// Create the command using bash -c to support pipes and redirection
	cmd := exec.Command("bash", "-c", shellCmd)

	// Capture both stdout and stderr
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	// Execute the command
	err := cmd.Run()

	// Check for execution errors
	if err != nil {
		// Include stderr in the error message for debugging
		errMsg := fmt.Sprintf("command execution failed: %v", err)
		if stderr.Len() > 0 {
			errMsg += fmt.Sprintf("\nstderr: %s", stderr.String())
		}
		return stdout.String(), fmt.Errorf("%s", errMsg)
	}

	// Check if stderr contains any warnings (non-fatal)
	if stderr.Len() > 0 {
		// Log warnings but don't treat as error
		fmt.Fprintf(os.Stderr, "Warning: %s\n", stderr.String())
	}

	return stdout.String(), nil
}

// shellEscape escapes special characters in a string for safe use in shell commands.
// This is a basic implementation; for production use, consider more robust escaping.
func shellEscape(s string) string {
	// Replace single quotes with '\'' sequence for safe quoting
	s = strings.ReplaceAll(s, "'", "'\\''")
	// Wrap in single quotes to prevent shell interpretation
	return "'" + s + "'"
}

// main function demonstrates the usage of QuerySLBAndExport
func main() {
	// Example usage - these would typically come from command-line arguments or configuration
